import{z as o,x as m,o as E,c as p,q as l,j as i,D as t,d as e,s as n,S as s,b as B}from"./chunks/framework.C8m1ZpeB.js";const S=JSON.parse('{"title":"美式提前行权与最优停","description":"","frontmatter":{"title":"美式提前行权与最优停","date":"2026-09-10T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/american-optimal-stop.md","filePath":"quant/american-optimal-stop.md","lastUpdated":1791063341000}'),A={name:"quant/american-optimal-stop.md"};function d(h,a,u,C,_,D){const r=m("Mermaid");return E(),p("div",null,[a[2]||(a[2]=l('<h1 id="美式提前行权与最优停" tabindex="-1">美式提前行权与最优停 <a class="header-anchor" href="#美式提前行权与最优停" aria-label="Permalink to &quot;美式提前行权与最优停&quot;">​</a></h1><div class="epigraph"><p>美式价格是停时类上的上确界：$V_0=\\sup_\\tau\\mathbb E_Q[\\mathrm e^{-r\\tau}g(S_\\tau)]$。提前行权当且仅当立即支付超过继续持有的条件期望。</p><footer>—— 据 Bensoussan, Acta Applicandae Mathematicae, 1984；Karatzas, 1988；Shreve, Stochastic Calculus for Finance II, 第 8 章整理</footer></div><p>上一课<a href="/quant/jump-process-intuition">跳过程直觉</a>留下不连续路径的接口。本课回到连续扩散，处理权利本身的时间：美式可在 \\([0,T]\\) 任一停时行权。缺口不是再写一遍欧式期望，而是把<a href="/quant/stopping-optional-sampling">停时与可选抽样</a>里的 \\(\\tau\\) 拿来做优化。本课只给最优停与 Snell 包络接口，不把自由边界数值做完；后课蒙特卡洛会用这条上确界当模拟对象。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>欧式把 \\(\\tau\\) 钉死为 \\(T\\)。美式允许持有人选 \\(\\tau\\le T\\)，价格是对所有停时取上确界。缺口是：这个上确界满足 \\(V_t=\\max\\bigl(g(S_t),\\,\\mathrm e^{-r\\Delta}\\mathbb E[V_{t+\\Delta}\\mid\\mathcal F_t]\\bigr)\\)（离散骨架），连续极限是变分不等式 \\(V\\ge g\\)，PDE 在继续区域内成立，在行权区域内取等 \\(V=g\\)。没有最优停，美式被误写成欧式再加一个「可能提前」的口头修正。</p><p>无股息看涨：在常数 \\(r\\gt 0\\) 下永不提前行权，美式等于欧式。看跌、有股息看涨，提前可能最优。这是接口，不是要在本课证完。</p><h3 id="最优停不是「看到最高点再行权」" tabindex="-1">最优停不是「看到最高点再行权」 <a class="header-anchor" href="#最优停不是「看到最高点再行权」" aria-label="Permalink to &quot;最优停不是「看到最高点再行权」&quot;">​</a></h3><p>那不是停时。最优 \\(\\tau^*\\) 是首次进入行权区域的时刻，区域由当时的 \\(S\\) 与剩余期限决定，不依赖未来路径。与停时课的反例同一条：不能用尚未实现的最大值。</p><p><span class="marginnote">Snell 包络是 supermartingale 的最小上界过程，在最优停时变成鞅。可选抽样保证：乱停只会更差或持平。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>\\(V_t=\\mathrm{ess\\,sup}_{\\tau\\in[t,T]}\\mathbb E_Q[\\mathrm e^{-r(\\tau-t)}g(S_\\tau)\\mid\\mathcal F_t]\\)。继续值 \\(C_t=\\mathbb E_Q[\\mathrm e^{-r\\mathrm d t}V_{t+\\mathrm d t}\\mid\\mathcal F_t]\\)，行权当 \\(g(S_t)\\ge C_t\\)。BSM 扩散下存在临界价 \\(S^*(t)\\)：看跌在 \\(S\\le S^*(t)\\) 行权。这是后课差分、树、Longstaff–Schwartz 回归的共同对象：都在近似 \\(C_t\\)。</p><p><span class="marginnote">数字实例：一张行权价 100 的看跌，标的价格跌到 90，立即行权拿 10 元；若还剩半年、波动率不低，继续持有的条件期望可能值 12 元——那该等。深度实值时反过来：标的跌到 50，行权几乎稳拿 50 元，落袋再吃利息往往更划算，所以看跌的行权区在低价一侧，临界价 \\(S^*(t)\\) 就是这条分界线。</span></p><p>跳会让区域出现「无触摸」带（跳跃越过边界），本课不展开，只声明接口仍是对停时取上确界，搜索空间没变。</p>',13)),(E(),i(s,null,{default:t(()=>[n(r,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20ST%5B%22%E5%81%9C%E6%97%B6%E7%B1%BB%22%5D%20--%3E%20SUP%5B%22%E4%B8%8A%E7%A1%AE%E7%95%8C%E5%8D%B3%E7%BE%8E%E5%BC%8F%E4%BB%B7%22%5D%0A%20%20SUP%20--%3E%20SNELL%5B%22Snell%20%E5%8C%85%E7%BB%9C%22%5D%0A%20%20SNELL%20--%3E%20EX%5B%22g%20%E5%A4%A7%E4%BA%8E%E7%BB%A7%E7%BB%AD%E5%80%BC%E5%88%99%E8%A1%8C%E6%9D%83%22%5D%0A%20%20SUP%20--%3E%20MC%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E8%B7%AF%E5%BE%84%E4%B8%8A%E4%BC%B0%E8%AE%A1%E7%BB%A7%E7%BB%AD%E5%80%BC%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=B("h2",{id:"机制",tabindex:"-1"},[e("机制 "),B("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=B("p",null,"继续值是「再等一瞬间」的复制价格，欧式课已经会算条件期望。美式多一个逐点 \\(\\max(g,\\cdot)\\)，破坏了纯 PDE 等式，改成互补：\\((V-g)\\cdot(\\text{PDE 残差})=0\\)。对冲在边界上 \\(\\Delta\\) 可能折拐（平滑粘贴在扩散情形常成立），Gamma 在边界附近变大。这是与欧式 delta 的差别，不是新的测度。离散时间把上确界收成从 \\(T\\) 向后的动态规划，树方法做的就是这件事；连续极限只是把网格加密。",-1)),(E(),i(s,null,{default:t(()=>[n(r,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20NOW%5B%22%E5%BD%93%E5%89%8D%E6%97%B6%E5%88%BB%20t%EF%BC%9A%E8%A7%82%E5%AF%9F%20S_t%22%5D%20--%3E%20CMP%7B%22%E6%AF%94%E4%B8%80%E6%AF%94%20g(S_t)%20%E4%B8%8E%E7%BB%A7%E7%BB%AD%E5%80%BC%20C_t%22%7D%0A%20%20CMP%20--%3E%7C%22g%20%E5%B0%8F%E4%BA%8E%20C%22%7C%20CON%5B%22%E7%BB%A7%E7%BB%AD%E5%8C%BA%EF%BC%9AV%20%E6%BB%A1%E8%B6%B3%20PDE%EF%BC%8C%E6%8E%A5%E7%9D%80%E7%AD%89%22%5D%0A%20%20CMP%20--%3E%7C%22g%20%E5%A4%A7%E4%BA%8E%E7%AD%89%E4%BA%8E%20C%22%7C%20EXR%5B%22%E8%A1%8C%E6%9D%83%E5%8C%BA%EF%BC%9AV%20%E8%B4%B4%E4%BD%8F%E5%86%85%E5%9C%A8%E4%BB%B7%E5%80%BC%20g%22%5D%0A%20%20CON%20--%3E%20BND%5B%22%E8%BE%B9%E7%95%8C%20S*(t)%EF%BC%9AV%20%E4%B8%8E%20g%20%E5%9C%A8%E6%AD%A4%E5%B9%B3%E6%BB%91%E7%B2%98%E8%B4%B4%22%5D%0A%20%20EXR%20--%3E%20BND%0A%20%20BND%20--%3E%20DRIFT%5B%22%E5%89%A9%E4%BD%99%E6%9C%9F%E9%99%90%E5%8F%98%E7%9F%AD%EF%BC%8C%E8%BE%B9%E7%95%8C%E9%9A%8F%E6%97%B6%E9%97%B4%E7%A7%BB%E5%8A%A8%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=l('<p><span class="marginnote">互补条件的直觉：两条规则——「\\(V\\) 至少值内在价值」和「\\(V\\) 按 PDE 自由演化」——不允许同时被违反。可以把 \\(V\\) 想成被底价托着的水面：贴着底价走的就是行权区，浮在底价上方的就是继续区，不存在既离开底价又不受 PDE 约束的状态。</span></p><p>无套利：美式价必须 \\(\\ge\\) 欧式价，且 \\(\\ge g\\mathrm e^{-r\\cdot 0}=g\\)（立即行权）。低于内在价值的报价可被立即行权套利。这不依赖 GBM。</p><p><span class="marginnote">常见误区：美式比欧式贵，不等于「早点行权更划算」。多出来的那部分钱买的是「可以等」的选择权本身。对无股息看涨，提前行权等于把尚未到期的时间价值白白扔掉，数学上可证明永不提前；真正促使提前行权的通常是现金流（股息、利息）。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不实现最小二乘蒙特卡洛，不画自由边界的渐近。不把百慕大、可转债的条款写全。后课默认：美式 $= $停时上确界；欧式是 \\(\\tau\\equiv T\\) 的特例；无股息看涨不提前。下一课<a href="/quant/mc-paths">蒙特卡洛路径</a>用模拟估计期望；美式需要在同一路径对象上再估继续值。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>美式价格是贴现支付在停时类上的上确界。</li><li>行权当立即支付不低于继续值；最优 \\(\\tau\\) 是首入行权区。</li><li>无股息看涨通常不提前；看跌与股息看涨会。</li><li>跳不改变上确界定义，只改变区域形状。</li><li>出处：Bensoussan 1984；Karatzas 1988；Shreve SDE II 第 8 章。</li></ul>',7))])}const g=o(A,[["render",d]]);export{S as __pageData,g as default};
